INSERT INTO hm_migration_assertion SELECT CASE WHEN (SELECT COUNT(*) FROM hm_customer)=0 AND (SELECT COUNT(*) FROM hm_order)=0 AND (SELECT COUNT(*) FROM hm_store)=0 THEN 1 ELSE 0 END;
INSERT INTO hm_migration_assertion SELECT CASE WHEN COUNT(*)=0 THEN 1 ELSE 0 END FROM hm_legacy_snapshot.hm_order o LEFT JOIN hm_legacy_snapshot.hm_customer_user c ON c.customer_id=o.customer_id LEFT JOIN hm_legacy_snapshot.hm_service_item s ON s.service_item_id=o.service_item_id WHERE c.customer_id IS NULL OR s.service_item_id IS NULL OR o.pay_amount<0 OR o.pay_amount>1000000 OR o.appointment_time_slot NOT REGEXP '^[0-2][0-9]:[03]0-[0-2][0-9]:[03]0$';
INSERT INTO hm_migration_assertion SELECT CASE WHEN COUNT(*)=0 THEN 1 ELSE 0 END FROM (SELECT order_id FROM hm_legacy_snapshot.hm_review WHERE status='0' GROUP BY order_id HAVING COUNT(*)>1) duplicates;
INSERT INTO hm_migration_assertion SELECT CASE WHEN COUNT(*)=0 THEN 1 ELSE 0 END FROM hm_legacy_snapshot.hm_customer_address a LEFT JOIN hm_legacy_snapshot.hm_customer_user c ON c.customer_id=a.customer_id WHERE c.customer_id IS NULL;
INSERT INTO hm_migration_assertion SELECT CASE WHEN COUNT(*)=0 THEN 1 ELSE 0 END FROM hm_legacy_snapshot.hm_order_assign a LEFT JOIN hm_legacy_snapshot.hm_worker_profile w ON w.worker_profile_id=a.worker_id LEFT JOIN hm_legacy_snapshot.sys_user u ON u.user_id=w.user_id WHERE a.assign_status<>'0' AND (w.worker_profile_id IS NULL OR u.user_id IS NULL);
INSERT INTO hm_migration_assertion SELECT CASE WHEN COUNT(*)=0 THEN 1 ELSE 0 END FROM hm_legacy_snapshot.hm_order WHERE RIGHT(appointment_time_slot,5)<=LEFT(appointment_time_slot,5);
INSERT INTO hm_migration_assertion SELECT CASE WHEN COUNT(*)=0 THEN 1 ELSE 0 END FROM (SELECT r.order_id,SUM(r.refund_amount) refunded,MAX(o.pay_amount) paid FROM hm_legacy_snapshot.hm_order_refund r JOIN hm_legacy_snapshot.hm_order o ON o.order_id=r.order_id WHERE r.finish_time IS NOT NULL GROUP BY r.order_id HAVING refunded>paid) invalid_refunds;
