-- Fresh destination only; source hm_legacy_snapshot must be a secured read-only backup.
-- Headquarters tenant 1; verify organization mapping and run without mysql --force.
CREATE TEMPORARY TABLE hm_migration_assertion (ok INT NOT NULL CHECK(ok=1));
START TRANSACTION;
-- Batch execution must abort on first error; never use mysql --force.
-- Archive source business fields for audit and subsequent migration. Session secrets remain only in the secured original backup.

 SELECT customer_id,mobile,COALESCE(nickname,''),COALESCE(avatar,''),CASE status WHEN '0' THEN 'ACTIVE' ELSE 'INACTIVE' END,COALESCE(create_time,CURRENT_TIMESTAMP)
 FROM hm_legacy_snapshot.hm_customer_user;
 SELECT 1,customer_id,CASE status WHEN '0' THEN 'ACTIVE' ELSE 'INACTIVE' END,COALESCE(source_channel,'LEGACY'),COALESCE(create_time,CURRENT_TIMESTAMP) FROM hm_legacy_snapshot.hm_customer_user;
 SELECT org_id,1,org_name,'',COALESCE(contact_mobile,''),CASE status WHEN '0' THEN 'ACTIVE' ELSE 'INACTIVE' END FROM hm_legacy_snapshot.hm_org;
 SELECT w.worker_profile_id,1,COALESCE(s.id,1),COALESCE(u.nick_name,u.user_name),COALESCE(u.phonenumber,''),COALESCE(w.intro,''),COALESCE(u.avatar,''),CASE w.status WHEN '0' THEN 'ACTIVE' ELSE 'INACTIVE' END
 FROM hm_legacy_snapshot.hm_worker_profile w JOIN hm_legacy_snapshot.sys_user u ON u.user_id=w.user_id LEFT JOIN hm_store s ON s.id=w.org_id AND s.tenant_id=1;
 SELECT category_id,1,category_name,COALESCE(category_icon,'') FROM hm_legacy_snapshot.hm_service_category;
 SELECT i.service_item_id,1,COALESCE(s.id,1),i.service_name,COALESCE(c.category_name,'家政服务'),COALESCE(i.service_desc,''),CAST(ROUND(i.base_price*100) AS SIGNED),GREATEST(30,COALESCE(i.service_duration,30)),COALESCE(i.service_cover,''),
 CASE WHEN i.status='0' AND i.del_flag='0' AND i.base_price>0 THEN 'ACTIVE' ELSE 'INACTIVE' END
 FROM hm_legacy_snapshot.hm_service_item i LEFT JOIN hm_legacy_snapshot.hm_service_category c ON c.category_id=i.category_id LEFT JOIN hm_store s ON s.id=i.org_id AND s.tenant_id=1;
 SELECT sku_id,1,service_item_id,sku_name,CAST(ROUND(price*100) AS SIGNED),GREATEST(30,COALESCE(duration_minute,30)),CASE WHEN status='0' AND price>0 THEN 'ACTIVE' ELSE 'INACTIVE' END FROM hm_legacy_snapshot.hm_service_sku;
 SELECT extra_item_id,1,service_item_id,extra_name,CAST(ROUND(extra_price*100) AS SIGNED),CASE status WHEN '0' THEN 'ACTIVE' ELSE 'INACTIVE' END FROM hm_legacy_snapshot.hm_service_extra_item;
 SELECT area_id,1,area_name,COALESCE(district_code,''),CAST(ROUND(extra_fee*100) AS SIGNED),CASE status WHEN '0' THEN 'ACTIVE' ELSE 'INACTIVE' END FROM hm_legacy_snapshot.hm_service_area;
 SELECT 1,service_item_id,GREATEST(0,min_advance_minutes),GREATEST(1,max_advance_days),allow_same_day='1',time_slots_json,cancel_rule_json FROM hm_legacy_snapshot.hm_booking_rule WHERE status='0';
 SELECT address_id,1,customer_id,contact_name,contact_mobile,CONCAT(COALESCE(province_name,''),COALESCE(city_name,''),COALESCE(district_name,''),detail_address),COALESCE(district_code,''),is_default='1' FROM hm_legacy_snapshot.hm_customer_address;
 SELECT o.order_id,1,o.customer_id,o.service_item_id,COALESCE(s.id,1),
 CAST(CONCAT(o.appointment_date,' ',LEFT(o.appointment_time_slot,5),':00') AS DATETIME),
 CAST(CONCAT(o.appointment_date,' ',RIGHT(o.appointment_time_slot,5),':00') AS DATETIME),
 CASE WHEN o.order_status IN ('60','70') THEN 'COMPLETED' WHEN o.order_status IN ('80','90') THEN 'CANCELLED' ELSE 'RESERVED' END,COALESCE(o.create_time,CURRENT_TIMESTAMP)
 FROM hm_legacy_snapshot.hm_order o LEFT JOIN hm_legacy_snapshot.hm_service_item i ON i.service_item_id=o.service_item_id LEFT JOIN hm_store s ON s.id=o.org_id AND s.tenant_id=1;
 SELECT o.order_id,1,o.customer_id,o.order_id,o.service_item_id,COALESCE(i.service_name,'历史服务'),COALESCE(s.id,1),CAST(ROUND(o.pay_amount*100) AS SIGNED),CASE o.pay_status WHEN '1' THEN CAST(ROUND(o.pay_amount*100) AS SIGNED) ELSE 0 END,
 CASE o.order_status WHEN '90' THEN CAST(ROUND(o.pay_amount*100) AS SIGNED) ELSE COALESCE((SELECT CAST(ROUND(SUM(r.refund_amount)*100) AS SIGNED) FROM hm_legacy_snapshot.hm_order_refund r WHERE r.order_id=o.order_id AND r.finish_time IS NOT NULL),0) END,
 CASE WHEN o.order_status IN ('20','30','40','50','60','70') AND o.pay_status<>'1' THEN 'MIGRATION_REVIEW' ELSE CASE o.order_status WHEN '10' THEN 'UNPAID' WHEN '20' THEN 'PAID' WHEN '30' THEN 'PAID' WHEN '40' THEN 'ASSIGNED' WHEN '50' THEN 'IN_SERVICE' WHEN '60' THEN 'COMPLETED' WHEN '70' THEN 'COMPLETED' WHEN '80' THEN 'CANCELLED' WHEN '90' THEN 'REFUNDED' ELSE 'MIGRATION_REVIEW' END END,
 o.contact_name,o.contact_mobile,o.service_address,CONCAT('legacy:',o.order_no),COALESCE(o.customer_remark,''),COALESCE(o.create_time,CURRENT_TIMESTAMP),o.pay_time,o.service_end_time
 FROM hm_legacy_snapshot.hm_order o LEFT JOIN hm_legacy_snapshot.hm_service_item i ON i.service_item_id=o.service_item_id LEFT JOIN hm_store s ON s.id=o.org_id AND s.tenant_id=1;
UPDATE hm_order o JOIN (SELECT order_id,MAX(assign_id) latest FROM hm_legacy_snapshot.hm_order_assign WHERE assign_status<>'0' GROUP BY order_id) x ON x.order_id=o.id
 JOIN hm_legacy_snapshot.hm_order_assign a ON a.assign_id=x.latest SET o.worker_id=a.worker_id WHERE o.tenant_id=1;
UPDATE hm_booking b JOIN hm_order o ON o.booking_id=b.id AND o.tenant_id=b.tenant_id SET b.worker_id=o.worker_id WHERE b.tenant_id=1;
 SELECT order_item_id,1,order_id,item_name,CAST(ROUND(item_price*100) AS SIGNED),quantity,CAST(ROUND(item_amount*100) AS SIGNED) FROM hm_legacy_snapshot.hm_order_item;
 SELECT log_id,1,order_id,action_type,operator_id,COALESCE(action_desc,''),COALESCE(create_time,CURRENT_TIMESTAMP) FROM hm_legacy_snapshot.hm_order_operate_log;
 SELECT review_id,1,customer_id,order_id,score,COALESCE(content,''),COALESCE(create_time,CURRENT_TIMESTAMP) FROM hm_legacy_snapshot.hm_review WHERE status='0';
 SELECT r.refund_id,1,o.customer_id,r.order_id,CAST(ROUND(r.refund_amount*100) AS SIGNED),COALESCE(r.refund_reason,''),CASE WHEN r.finish_time IS NOT NULL THEN 'REFUNDED' ELSE 'MIGRATION_REVIEW' END,COALESCE(r.apply_time,CURRENT_TIMESTAMP)
 FROM hm_legacy_snapshot.hm_order_refund r JOIN hm_legacy_snapshot.hm_order o ON o.order_id=r.order_id WHERE r.refund_amount>0;
 SELECT content_id,1,content_type,title,COALESCE(summary,''),content_html,COALESCE(cover_image,''),publish_status='1' FROM hm_legacy_snapshot.hm_portal_content;
-- Rebuild occupied slots; overlapping historical assignments fail instead of permitting double booking.
 SELECT b.tenant_id,b.worker_id,TIMESTAMPADD(MINUTE,n.n*30,b.starts_at),b.id FROM hm_booking b
 JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15) n
 ON TIMESTAMPADD(MINUTE,n.n*30,b.starts_at)<b.ends_at
 WHERE b.tenant_id=1 AND b.worker_id IS NOT NULL AND b.status='RESERVED';
COMMIT;
DROP TEMPORARY TABLE hm_migration_assertion;
